WITH filtered AS (SELECT id, name, email, city, is_active, credit_limit, age, DATE_ADD(signup_date, 25) AS signup_date_plus_25d FROM customers WHERE signup_date >= TO_DATE('2023-05-26') AND segment IN ('Corporate', 'SMB', 'Consumer')), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY credit_limit DESC NULLS FIRST, id) AS dedup_rank FROM filtered QUALIFY dedup_rank = 1), remaining_keys AS (SELECT id, city FROM ranked INTERSECT ALL SELECT id, city FROM customers WHERE LENGTH(name) > 12), reconciled AS (SELECT s.* FROM ranked s INNER JOIN remaining_keys k ON s.id = k.id AND s.city = k.city), eligible AS (SELECT s.* FROM reconciled s WHERE NOT EXISTS (SELECT 1 FROM accounts ch WHERE ch.customer_id = s.id AND ch.opened_date >= s.signup_date_plus_25d)), with_windows AS (SELECT *, CUME_DIST() OVER (ORDER BY age DESC NULLS FIRST) AS age_cume_dist, PERCENT_RANK() OVER (PARTITION BY city ORDER BY age DESC NULLS LAST) AS age_percent_rank, PERCENT_RANK() OVER (ORDER BY credit_limit NULLS FIRST) AS credit_limit_percent_rank, CUME_DIST() OVER (PARTITION BY city ORDER BY age NULLS FIRST) AS age_cume_dist_2, DENSE_RANK() OVER (ORDER BY credit_limit) AS credit_limit_dense_rank FROM eligible) SELECT DATE_TRUNC('QUARTER', signup_date_plus_25d) AS quarter_start, city, SORT_ARRAY(COLLECT_SET(city)) AS city_list, STDDEV_SAMP(credit_limit) AS credit_limit_stddev, ROUND(AVG(credit_limit), 2) AS avg_credit_limit FROM with_windows GROUP BY 1, 2;
